 const cache=new Map(), pending=new Map(); let next=1;
 const run=(tool,args)=>{let error='';const budget=tool.maxAttempts||1;for(let n=1;n<=budget;n++){try{return {ok:true,value:tool.handler(args),attempts:n};}catch(e){error=e.message;}}return {ok:false,reason:'tool_failed',attempts:budget,error};};
