  for(const field of Object.keys(schema)){const r=schema[field];let problem;if(!Object.prototype.hasOwnProperty.call(request,field)){if(r.required)problem='missing';}else if(typeof request[field]!==r.type)problem='type';else if(r.enum&&!r.enum.includes(request[field]))problem='enum';if(problem)return {ok:false,reason:'invalid_arguments',field,problem};}
